# Registry of the generated Cake StepFun fused-MoE programs (filled verbatim by
# the Cake generated-program export; do not edit the literals by hand).
#
# ``PROGRAMS``: one record per physical program -- one kernel source plus its
# host binding, shared by every architecture in ``arches`` -- with its
# architecture-free ``library`` stem, FFI entry, argument plan (the binding's
# positional order; ``cake_launch`` derives the launcher from it), launch shape
# and the stage metadata ``unit`` (stage, family / tile or variant, dtypes,
# the storage dtype the binding checks per tensor argument, ...).  What to
# compile (the translation units, the compile flags, the per-architecture
# closure digest) is recorded in ``build.json`` (see ``cake_build``), whose
# entry for a program is ``<library>_<arch>``; a program is built once per
# architecture, prebuilt under ``aot/`` or by FlashInfer's JIT.
#
# ``STAGE_TABLES``: the five dispatch tables of the pipeline (``routing``,
# ``fc1``, ``requant``, ``fc2``, ``finalize``) as ordered program-name lists;
# every row fact lives once, in ``PROGRAMS[name]["unit"]``.  The routing table
# is in dispatcher order (per input kind and logits dtype, ascending token
# windows); the two histogram pre-programs of the cooperative rows are reached
# through ``unit["pre"]`` only.
#
# ``ROUTES``: one record per measured route (per-stage units and the full
# routing -> FC1 -> [requant] -> FC2 -> finalize path per family and tile)
# naming its architectures, token count and ordered stages.
#
# ``HOST_PLAN_CONSTANTS``: the geometry, family, routing, requantization and
# finalize constants the package backend's host plan evaluates.
